ALTER TABLE public.org_members ADD COLUMN active boolean NOT NULL DEFAULT true;
ALTER TABLE public.organisations ADD COLUMN firm_address text NOT NULL DEFAULT '', ADD COLUMN base_currency text NOT NULL DEFAULT 'EUR', ADD COLUMN require_2fa boolean NOT NULL DEFAULT false;
CREATE TABLE public.org_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE, email text NOT NULL, role public.app_role NOT NULL, token_hash text NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', revoked_at timestamptz, accepted_at timestamptz, accepted_by uuid, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.org_invites TO authenticated;
GRANT ALL ON public.org_invites TO service_role;
ALTER TABLE public.org_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY invites_admin_read ON public.org_invites FOR SELECT TO authenticated USING (public.has_org_role(org_id,ARRAY['org_admin']::public.app_role[]));
CREATE TRIGGER audit_org_invites AFTER INSERT OR UPDATE OR DELETE ON public.org_invites FOR EACH ROW EXECUTE FUNCTION public.audit_capture();
CREATE OR REPLACE FUNCTION public.audit_minimise(_table text,_row jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN _row IS NULL THEN NULL WHEN _table='org_invites' THEN _row-ARRAY['token_hash','email'] WHEN _table='complaints' THEN _row-ARRAY['complainant_name','complainant_email','complainant_phone','customer_ref','vulnerable_note','summary','desired_outcome','holding_reason','root_cause_note','root_cause_category'] WHEN _table='complaint_events' THEN _row-'detail' WHEN _table='letters' THEN _row-ARRAY['subject','body'] WHEN _table='qa_reviews' THEN _row-ARRAY['comments','scorecard'] WHEN _table='notifications' THEN _row-'title' WHEN _table='public_form_submissions' THEN _row-'privacy_notice' ELSE _row END $$;
CREATE OR REPLACE FUNCTION public.is_org_member(_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.org_members m JOIN public.organisations o ON o.id=m.org_id JOIN auth.users u ON u.id=m.user_id WHERE m.org_id=_org AND m.user_id=auth.uid() AND m.active AND u.email_confirmed_at IS NOT NULL AND (NOT o.require_2fa OR auth.jwt()->>'aal'='aal2')) $$;
CREATE OR REPLACE FUNCTION public.has_org_role(_org uuid,_roles public.app_role[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_org_member(_org) AND EXISTS(SELECT 1 FROM public.org_members WHERE org_id=_org AND user_id=auth.uid() AND active AND role=ANY(_roles)) $$;
CREATE POLICY members_self_access_state ON public.org_members FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.my_organisations() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(jsonb_agg(jsonb_build_object('org_id',o.id,'legal_name',o.legal_name,'role',m.role,'active',m.active,'require_2fa',o.require_2fa,'setup_complete',o.setup_complete) ORDER BY o.legal_name),'[]'::jsonb) FROM public.org_members m JOIN public.organisations o ON o.id=m.org_id WHERE m.user_id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.my_organisations() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_organisations() TO authenticated;
CREATE OR REPLACE FUNCTION public.member_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
PERFORM 1 FROM public.organisations WHERE id=COALESCE(NEW.org_id,OLD.org_id) FOR UPDATE;
IF TG_OP='UPDATE' AND (NEW.org_id<>OLD.org_id OR NEW.user_id<>OLD.user_id) THEN RAISE EXCEPTION 'Membership identity cannot change'; END IF;
IF TG_OP IN ('UPDATE','DELETE') AND OLD.active AND OLD.role='org_admin' AND (TG_OP='DELETE' OR NOT NEW.active OR NEW.role<>'org_admin') AND NOT EXISTS(SELECT 1 FROM public.org_members WHERE org_id=OLD.org_id AND id<>OLD.id AND active AND role='org_admin') THEN RAISE EXCEPTION 'The last active Org Admin must be retained'; END IF;
IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Deactivate memberships instead of deleting them'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER members_identity_last_admin BEFORE UPDATE OR DELETE ON public.org_members FOR EACH ROW EXECUTE FUNCTION public.member_guard();
REVOKE INSERT,UPDATE,DELETE ON public.org_members FROM authenticated;
CREATE OR REPLACE FUNCTION public.change_org_member(_org uuid,_member uuid,_role public.app_role,_active boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins can manage members'; END IF; PERFORM 1 FROM public.organisations WHERE id=_org FOR UPDATE; UPDATE public.org_members SET role=_role,active=_active WHERE id=_member AND org_id=_org; IF NOT FOUND THEN RAISE EXCEPTION 'Member not found'; END IF; END $$;
REVOKE ALL ON FUNCTION public.change_org_member(uuid,uuid,public.app_role,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.change_org_member(uuid,uuid,public.app_role,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.transfer_org_admin(_org uuid,_member uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins can transfer'; END IF; PERFORM 1 FROM public.organisations WHERE id=_org FOR UPDATE; UPDATE public.org_members SET role='org_admin' WHERE org_id=_org AND id=_member AND active AND user_id<>auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Select another active member'; END IF; UPDATE public.org_members SET role='complaints_manager' WHERE org_id=_org AND user_id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.transfer_org_admin(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.transfer_org_admin(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.create_org_invite(_org uuid,_email text,_role public.app_role,_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins can invite'; END IF; IF _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(_email)>255 OR length(_hash)<>64 THEN RAISE EXCEPTION 'Invalid invitation'; END IF; PERFORM 1 FROM public.organisations WHERE id=_org AND setup_complete FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Complete organisation setup first'; END IF; UPDATE public.org_invites SET revoked_at=now() WHERE org_id=_org AND email=lower(trim(_email)) AND accepted_at IS NULL AND revoked_at IS NULL; INSERT INTO public.org_invites(org_id,email,role,token_hash,created_by) VALUES(_org,lower(trim(_email)),_role,_hash,auth.uid()) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.create_org_invite(uuid,text,public.app_role,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_org_invite(uuid,text,public.app_role,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.revoke_org_invite(_org uuid,_invite uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins can revoke'; END IF; UPDATE public.org_invites SET revoked_at=now() WHERE id=_invite AND org_id=_org AND accepted_at IS NULL; END $$;
REVOKE ALL ON FUNCTION public.revoke_org_invite(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.revoke_org_invite(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.accept_org_invite(_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.org_invites; em text; BEGIN SELECT lower(email) INTO em FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; IF em IS NULL THEN RAISE EXCEPTION 'Sign in with a verified email first'; END IF; SELECT * INTO i FROM public.org_invites WHERE token_hash=_hash FOR UPDATE; IF i.id IS NULL OR i.revoked_at IS NOT NULL OR i.expires_at<=now() OR i.accepted_at IS NOT NULL OR i.email<>em THEN RAISE EXCEPTION 'Invitation is unavailable or belongs to another email'; END IF; PERFORM 1 FROM public.organisations WHERE id=i.org_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.org_members WHERE org_id=i.org_id AND user_id=auth.uid() AND NOT active) THEN RAISE EXCEPTION 'An Org Admin must reactivate your membership'; END IF; IF EXISTS(SELECT 1 FROM public.org_members WHERE org_id=i.org_id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'You already belong to this organisation'; END IF; INSERT INTO public.org_members(org_id,user_id,role) VALUES(i.org_id,auth.uid(),i.role); UPDATE public.org_invites SET accepted_at=now(),accepted_by=auth.uid() WHERE id=i.id; RETURN i.org_id; END $$;
REVOKE ALL ON FUNCTION public.accept_org_invite(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.accept_org_invite(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.assignment_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.assigned_to IS NOT NULL AND (TG_OP='INSERT' OR NEW.assigned_to IS DISTINCT FROM OLD.assigned_to) AND NOT EXISTS(SELECT 1 FROM public.org_members WHERE org_id=NEW.org_id AND user_id=NEW.assigned_to AND active AND role<>'read_only') THEN RAISE EXCEPTION 'Assignments require an active case handler in this organisation'; END IF; IF NEW.rule_set_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.rule_sets WHERE org_id=NEW.org_id AND id=NEW.rule_set_id) THEN RAISE EXCEPTION 'Rule set belongs to another organisation'; END IF; RETURN NEW; END $$;
CREATE TRIGGER complaints_assignment_guard BEFORE INSERT OR UPDATE ON public.complaints FOR EACH ROW EXECUTE FUNCTION public.assignment_guard();
CREATE OR REPLACE FUNCTION public.rule_assignment_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.rule_sets WHERE org_id=NEW.org_id AND id=NEW.rule_set_id) THEN RAISE EXCEPTION 'Rule set belongs to another organisation'; END IF; IF NEW.country_code IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.org_countries WHERE org_id=NEW.org_id AND country_code=NEW.country_code) THEN RAISE EXCEPTION 'Country is not served'; END IF; IF NEW.product IS NOT NULL AND NEW.product NOT IN ('payment_account','card','credit_transfer','direct_debit','e_money_wallet','merchant_acquiring','other') THEN RAISE EXCEPTION 'Invalid product'; END IF; RETURN NEW; END $$;
CREATE TRIGGER rule_assignment_tenant_guard BEFORE INSERT OR UPDATE ON public.rule_set_assignments FOR EACH ROW EXECUTE FUNCTION public.rule_assignment_guard();
CREATE OR REPLACE FUNCTION public.save_rule_assignment(_org uuid,_rule uuid,_country text,_product text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins can assign rules'; END IF; PERFORM 1 FROM public.organisations WHERE id=_org FOR UPDATE; DELETE FROM public.rule_set_assignments WHERE org_id=_org AND country_code IS NOT DISTINCT FROM _country AND product IS NOT DISTINCT FROM _product; INSERT INTO public.rule_set_assignments(org_id,rule_set_id,country_code,product) VALUES(_org,_rule,_country,_product); END $$;
REVOKE ALL ON FUNCTION public.save_rule_assignment(uuid,uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_rule_assignment(uuid,uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.set_default_rule(_org uuid,_rule uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) OR NOT EXISTS(SELECT 1 FROM public.rule_sets WHERE id=_rule AND org_id=_org) THEN RAISE EXCEPTION 'Rule unavailable'; END IF; PERFORM 1 FROM public.organisations WHERE id=_org FOR UPDATE; UPDATE public.rule_sets SET is_default=(id=_rule) WHERE org_id=_org; END $$;
REVOKE ALL ON FUNCTION public.set_default_rule(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_default_rule(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.recalculate_complaint(_org uuid,_case uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.complaints; r public.rule_sets; d date; BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins can recalculate'; END IF; IF length(trim(_reason)) NOT BETWEEN 10 AND 1000 THEN RAISE EXCEPTION 'A reason of at least 10 characters is required'; END IF; SELECT * INTO c FROM public.complaints WHERE org_id=_org AND id=_case AND anonymised_at IS NULL AND NOT privacy_processing FOR UPDATE; IF c.id IS NULL THEN RAISE EXCEPTION 'Complaint unavailable'; END IF; SELECT * INTO r FROM public.rule_sets WHERE id=public.resolve_rule_set(_org,c.country_code,c.product::text); d:=(c.received_at AT TIME ZONE 'UTC')::date; UPDATE public.complaints SET rule_set_id=r.id,ack_due=public.add_business_days(_org,c.country_code,d,r.ack_days),final_due=public.add_business_days(_org,c.country_code,d,r.final_days),extended_due=public.add_business_days(_org,c.country_code,d,r.extended_days) WHERE id=_case; INSERT INTO public.complaint_events(org_id,complaint_id,actor,kind,detail) VALUES(_org,_case,auth.uid(),'deadline_recalculated',jsonb_build_object('reason',_reason,'previous_ack',c.ack_due,'previous_final',c.final_due,'previous_extended',c.extended_due,'rule_set',r.id)); END $$;
REVOKE ALL ON FUNCTION public.recalculate_complaint(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.recalculate_complaint(uuid,uuid,text) TO authenticated;